% 数据
n = 20;
w = randi([1, 10], 1, n);
v = randi([1, 20], 1, n);
W = 50;

% 适应度函数（带惩罚）
function fit = knapsack_fitness(x)
    total_w = sum(w .* x);
    total_v = sum(v .* x);
    if total_w > W
    fit = total_v - 100 * (total_w - W); % 惩罚
    else
    fit = total_v;
    end
end
